import pandas as pd
import ast
import json

def parse_json_list(x):
    if isinstance(x, str):
        try:
            # The data seems to be a string representation of a list of strings
            # e.g., '["prompt1", "prompt2"]'
            # or just 'prompt1'
            data = ast.literal_eval(x)
            if isinstance(data, list):
                return " ".join(data)
            return str(data)
        except:
            return str(x)
    return str(x)

def main():
    train = pd.read_csv('data/train.csv')

    # Columns to process
    # prompt, response_a, response_b
    train['prompt'] = train['prompt'].apply(parse_json_list)
    train['response_a'] = train['response_a'].apply(parse_json_list)
    train['response_b'] = train['response_b'].apply(parse_json_list)

    test = pd.read_csv('data/test.csv')
    test['prompt'] = test['prompt'].apply(parse_json_list)
    test['response_a'] = test['response_a'].apply(parse_json_list)
    test['response_b'] = test['response_b'].apply(parse_json_list)

    train.to_csv('data/train_processed.csv', index=False)
    test.to_csv('data/test_processed.csv', index=False)
    print("Preprocessing complete.")

if __name__ == "__main__":
    main()
